export function media(slug: string): MediaAsset {
  const found = MEDIA.find((m) => m.slug === slug);
  if (!found) throw new Error(`Unknown media asset: ${slug}`);
  return found;
}

export function mediaFor(collection: string): MediaAsset[] {
  return MEDIA.filter((m) => m.collection === collection);
}
